/**
 * Probe baseline review packet — the evidence an independent reviewer reads
 * before signing `eval/baselines/probes.approval.json`.
 *
 * Read-only by construction: it renders per-changed-probe before/after top-10
 * tables, metric deltas against the reviewed budgets, and a digest footer
 * printing exactly the values the approval must bind. It never writes the
 * approval — authoring that record is the reviewer's act, not this tool's
 * (docs/governance/probe-baseline-review.md).
 *
 * Output is deterministic (no timestamps, no environment) so a packet can be
 * regenerated byte-identically from the same inputs and compared.
 */

import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import { parseVerseId } from '@jestek-dev/scripture-engine/internal';

import { BOOKS } from '../../pipeline/src/books.js';
import {
  canonicalJsonSha256,
  type Probe,
  type ProbeBaseline,
  type ProbeObservation,
} from './gates/probes.js';
import {
  BATTERY_JUDGMENTS_PATH,
  BATTERY_QUERIES_PATH,
  type RankAggregate,
  type RankMetricValue,
  type RankMetricsBaseline,
} from './gates/rankMetrics.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const EVAL_ROOT = join(HERE, '..');

export interface ReviewPacketNoiseBudgets {
  readonly maxTop10ChurnRatio: number;
  readonly maxWeakReasonShareIncrease: number;
}

export interface ReviewPacketRankInput {
  /** Null for the bootstrap review: no prior rank baseline exists to chain. */
  readonly before: RankMetricsBaseline | null;
  readonly after: RankMetricsBaseline;
  /** Byte digests of the battery files the metrics were computed from. */
  readonly batteryQueriesSha256: string;
  readonly batteryJudgmentsSha256: string;
}

export interface BaselineReviewPacketInput {
  readonly before: ProbeBaseline;
  readonly after: ProbeBaseline;
  readonly probeFile: { readonly probes: readonly Probe[] };
  readonly noise: ReviewPacketNoiseBudgets;
  /** Present only when a rank-metrics baseline move is under review (E5). */
  readonly rank?: ReviewPacketRankInput;
}

const BOOK_NAMES = new Map(BOOKS.map((book) => [book.id, book.name]));

/** `WEB:45005008` -> `Romans 5:8 (WEB)`; anything undecodable passes through. */
export function describeTargetId(targetId: string): string {
  const match = /^([A-Za-z0-9]+):(\d{7,8})$/.exec(targetId);
  if (match === null) return `\`${targetId}\``;
  try {
    const { bookId, chapter, verse } = parseVerseId(Number(match[2]));
    const book = BOOK_NAMES.get(bookId);
    if (book === undefined) return `\`${targetId}\``;
    return `\`${targetId}\` ${book} ${chapter}:${verse}`;
  } catch {
    return `\`${targetId}\``;
  }
}

function churnRatio(previous: readonly string[], current: readonly string[]): number {
  if (previous.length === 0) return current.length > 0 ? 1 : 0;
  const now = new Set(current);
  return previous.filter((id) => !now.has(id)).length / previous.length;
}

function ratio(value: number): string {
  return `${(value * 100).toFixed(0)}%`;
}

function signed(value: number): string {
  const rounded = Number(value.toFixed(6));
  return rounded > 0 ? `+${rounded}` : `${rounded}`;
}

function observationChanged(before: ProbeObservation, after: ProbeObservation): boolean {
  return JSON.stringify(before) !== JSON.stringify(after);
}

function movementRows(before: ProbeObservation, after: ProbeObservation): string[] {
  const beforeRanks = new Map(before.top.map((id, index) => [id, index + 1]));
  const afterIds = new Set(after.top);
  const rows: string[] = [
    '| # | before | after | movement |',
    '|---|---|---|---|',
  ];
  const depth = Math.max(before.top.length, after.top.length);
  for (let index = 0; index < depth; index += 1) {
    const beforeId = before.top[index];
    const afterId = after.top[index];
    let marker = '';
    if (afterId !== undefined) {
      const wasAt = beforeRanks.get(afterId);
      if (wasAt === undefined) marker = '**added**';
      else if (wasAt !== index + 1) marker = `moved (was #${wasAt})`;
      else marker = 'held';
    }
    rows.push(
      `| ${index + 1} ` +
        `| ${beforeId === undefined ? '' : describeTargetId(beforeId)} ` +
        `| ${afterId === undefined ? '' : describeTargetId(afterId)} ` +
        `| ${marker} |`,
    );
  }
  const dropped = before.top.filter((id) => !afterIds.has(id));
  if (dropped.length > 0) {
    rows.push('', `Dropped from the top-10: ${dropped.map(describeTargetId).join(', ')}`);
  }
  return rows;
}

function probeSection(
  probe: Probe | undefined,
  probeId: string,
  before: ProbeObservation,
  after: ProbeObservation,
  noise: ReviewPacketNoiseBudgets,
): string[] {
  const churn = churnRatio(before.top, after.top);
  const weakRise = Number((after.weakReasonShare - before.weakReasonShare).toFixed(6));
  const lines: string[] = [
    `### \`${probeId}\`${probe === undefined ? '' : ` — "${probe.query}" (${probe.kind})`}`,
    '',
  ];
  if (probe?.why !== undefined) lines.push(`> ${probe.why}`, '');
  lines.push(
    '| metric | before | after | delta | budget |',
    '|---|---|---|---|---|',
    `| result count | ${before.resultCount} | ${after.resultCount} | ${signed(after.resultCount - before.resultCount)} | — |`,
    `| top-10 churn | — | ${ratio(churn)} | — | max ${ratio(noise.maxTop10ChurnRatio)}${churn > noise.maxTop10ChurnRatio ? ' — **EXCEEDED**' : ''} |`,
    `| weak-reason share | ${before.weakReasonShare} | ${after.weakReasonShare} | ${signed(weakRise)} | rise max ${signed(noise.maxWeakReasonShareIncrease)}${weakRise > noise.maxWeakReasonShareIncrease ? ' — **EXCEEDED**' : ''} |`,
    `| mean top score | ${before.meanTopScore} | ${after.meanTopScore} | ${signed(after.meanTopScore - before.meanTopScore)} | — |`,
    '',
  );
  if (probe?.expectNoResults === true) {
    lines.push(
      after.resultCount === 0
        ? 'Adversarial probe: must return nothing, and still does.'
        : `**Adversarial probe returns ${after.resultCount} result(s) but must return none.**`,
      '',
    );
  }
  lines.push(...movementRows(before, after), '');
  return lines;
}

function displayRankMicro(micro: number | null): string {
  return micro === null ? 'n/a' : (micro / 1000000).toFixed(6);
}

/** `0.850000 → 0.877142 (+0.027142)`; a side with no value renders honestly. */
function rankMovementCell(before: RankMetricValue | undefined, after: RankMetricValue | undefined): string {
  const left = before === undefined ? '—' : displayRankMicro(before.micro);
  const right = after === undefined ? '—' : displayRankMicro(after.micro);
  if (before?.micro == null || after?.micro == null) return `${left} → ${right}`;
  const deltaMicro = after.micro - before.micro;
  const magnitude = (Math.abs(deltaMicro) / 1000000).toFixed(6);
  return `${left} → ${right} (${deltaMicro < 0 ? '-' : '+'}${magnitude})`;
}

function rankMovementRows(
  before: RankMetricsBaseline | null,
  after: RankMetricsBaseline,
): string[] {
  const labels = ['overall', ...[...new Set([
    ...Object.keys(before?.perCategory ?? {}),
    ...Object.keys(after.perCategory),
  ])].sort()];
  const aggregateOf = (baseline: RankMetricsBaseline | null, label: string): RankAggregate | undefined =>
    baseline === null ? undefined : label === 'overall' ? baseline.overall : baseline.perCategory[label];
  if (before === null) {
    return [
      '| Category | nDCG@10 | MRR@10 | good-or-better@3 | Recall@50 |',
      '|---|---|---|---|---|',
      ...labels.map((label) => {
        const aggregate = aggregateOf(after, label);
        const cell = (value: RankMetricValue | undefined): string =>
          value === undefined ? '—' : `${displayRankMicro(value.micro)} (new)`;
        return `| ${label} | ${cell(aggregate?.ndcg10)} | ${cell(aggregate?.mrr10)} ` +
          `| ${cell(aggregate?.goodOrBetterTop3Rate)} | ${cell(aggregate?.recallAt50)} |`;
      }),
    ];
  }
  return [
    '| Category | nDCG@10 | MRR@10 | good-or-better@3 | Recall@50 |',
    '|---|---|---|---|---|',
    ...labels.map((label) => {
      const left = aggregateOf(before, label);
      const right = aggregateOf(after, label);
      return `| ${label} | ${rankMovementCell(left?.ndcg10, right?.ndcg10)} ` +
        `| ${rankMovementCell(left?.mrr10, right?.mrr10)} ` +
        `| ${rankMovementCell(left?.goodOrBetterTop3Rate, right?.goodOrBetterTop3Rate)} ` +
        `| ${rankMovementCell(left?.recallAt50, right?.recallAt50)} |`;
    }),
  ];
}

function rankSection(rank: ReviewPacketRankInput): string[] {
  const lines: string[] = [
    '## Rank-metrics movement',
    '',
  ];
  if (rank.before === null) {
    lines.push(
      'This is a **bootstrap** review: no prior rank-metrics baseline exists, so the',
      'approval\'s `priorProvenance` is null beside an explicit `bootstrap` field',
      'documenting that fact. Values below are new, not deltas.',
      '',
    );
  }
  lines.push(...rankMovementRows(rank.before, rank.after), '');
  lines.push(
    '### The rank-metrics approval must bind exactly these values',
    '',
    'Copied into `eval/baselines/rank-metrics.approval.json` by the reviewer; the',
    'gauntlet recomputes and compares every one of them, and thresholds in',
    '`eval/budgets.json` `rankQuality` may flip from null only against this',
    'approved baseline.',
    '',
    `- \`baselineSha256\`: \`${canonicalJsonSha256(rank.after)}\` (canonical JSON of the after rank-metrics baseline)`,
    `- \`batteryQueriesSha256\`: \`${rank.batteryQueriesSha256}\` (bytes of \`${BATTERY_QUERIES_PATH}\`)`,
    `- \`batteryJudgmentsSha256\`: \`${rank.batteryJudgmentsSha256}\` (bytes of \`${BATTERY_JUDGMENTS_PATH}\`)`,
    `- \`engine.engineVersion\`: \`${rank.after.engineVersion}\``,
    `- \`engine.corpusFingerprint\`: \`${rank.after.corpusFingerprint}\``,
    `- \`engine.layerFingerprint\`: \`${rank.after.layerFingerprint}\``,
    '',
  );
  if (rank.before !== null) {
    lines.push(
      `For the review record: the before rank baseline's canonical-JSON SHA-256 is`,
      `\`${canonicalJsonSha256(rank.before)}\`; \`priorProvenance.baselineGitBlobSha1\` comes from`,
      '`git rev-parse <before-revision>:eval/baselines/rank-metrics.json`.',
      '',
    );
  }
  return lines;
}

export function renderBaselineReviewPacket(input: BaselineReviewPacketInput): string {
  const { before, after, probeFile, noise } = input;
  const probesById = new Map(probeFile.probes.map((probe) => [probe.id, probe]));
  const beforeById = new Map(before.observations.map((entry) => [entry.id, entry]));
  const afterById = new Map(after.observations.map((entry) => [entry.id, entry]));
  const ids = [...new Set([...beforeById.keys(), ...afterById.keys()])].sort();

  const changed = ids.filter((id) => {
    const left = beforeById.get(id);
    const right = afterById.get(id);
    return left !== undefined && right !== undefined && observationChanged(left, right);
  });
  const unchanged = ids.filter((id) => {
    const left = beforeById.get(id);
    const right = afterById.get(id);
    return left !== undefined && right !== undefined && !observationChanged(left, right);
  });
  const onlyBefore = ids.filter((id) => !afterById.has(id));
  const onlyAfter = ids.filter((id) => !beforeById.has(id));

  const lines: string[] = [
    '# Probe baseline review packet',
    '',
    'Read-only evidence for the independent baseline reviewer',
    '(docs/governance/probe-baseline-review.md). This packet is generated from the',
    'exact before/after baseline documents; it never writes the approval.',
    '',
    '## Engine identity movement',
    '',
    '| | before | after |',
    '|---|---|---|',
    `| engineVersion | \`${before.engineVersion}\` | \`${after.engineVersion}\` |`,
    `| corpusFingerprint | \`${before.corpusFingerprint}\` | \`${after.corpusFingerprint}\` |`,
    `| layerFingerprint | \`${before.layerFingerprint}\` | \`${after.layerFingerprint}\` |`,
    '',
    '## Probe movement summary',
    '',
    `- ${ids.length} probe(s): ${changed.length} changed, ${unchanged.length} unchanged.`,
    `- Unchanged: ${unchanged.map((id) => `\`${id}\``).join(', ') || 'none'}.`,
  ];
  if (onlyBefore.length > 0) lines.push(`- **Removed from the probe set**: ${onlyBefore.map((id) => `\`${id}\``).join(', ')}.`);
  if (onlyAfter.length > 0) lines.push(`- **New in the probe set**: ${onlyAfter.map((id) => `\`${id}\``).join(', ')}.`);
  lines.push('', '## Changed probes', '');
  if (changed.length === 0) lines.push('No probe observation changed between the two baselines.', '');
  for (const id of changed) {
    lines.push(...probeSection(probesById.get(id), id, beforeById.get(id)!, afterById.get(id)!, noise));
  }
  if (input.rank !== undefined) lines.push(...rankSection(input.rank));
  lines.push(
    '## The approval must bind exactly these values',
    '',
    'Copied into `eval/baselines/probes.approval.json` by the reviewer; the',
    'gauntlet recomputes and compares every one of them.',
    '',
    `- \`baselineSha256\`: \`${canonicalJsonSha256(after)}\` (canonical JSON of the after baseline)`,
    `- \`probesSha256\`: \`${canonicalJsonSha256(probeFile)}\` (canonical JSON of the probe definitions file)`,
    `- \`engine.engineVersion\`: \`${after.engineVersion}\``,
    `- \`engine.corpusFingerprint\`: \`${after.corpusFingerprint}\``,
    `- \`engine.layerFingerprint\`: \`${after.layerFingerprint}\``,
    '',
    'A v2 approval also quotes `reviewPacketSha256`: the SHA-256 of this packet',
    'file exactly as written. The tool prints it on stderr when it generates the',
    'packet, and `sha256sum` on the saved packet reproduces it.',
    '',
    `For the review record: the before baseline's canonical-JSON SHA-256 is`,
    `\`${canonicalJsonSha256(before)}\`; \`priorProvenance.baselineGitBlobSha1\` comes from`,
    '`git rev-parse <before-revision>:eval/baselines/probes.json`.',
    '',
  );
  return lines.join('\n');
}

/**
 * The digest a v2 approval quotes as `reviewPacketSha256`: SHA-256 of the
 * packet file exactly as this tool writes it (the rendered markdown plus the
 * trailing newline), so `sha256sum <packet>.md` reproduces it.
 */
export function reviewPacketSha256(packet: string): string {
  return createHash('sha256').update(`${packet}\n`, 'utf8').digest('hex');
}

function parseArguments(argv: readonly string[]): Map<string, string> {
  const known = new Set(['--before', '--after', '--probes', '--budgets', '--out', '--rank-before', '--rank-after']);
  const values = new Map<string, string>();
  for (let index = 0; index < argv.length; index += 2) {
    const flag = argv[index]!;
    const value = argv[index + 1];
    if (!known.has(flag)) throw new Error(`Unknown review-packet argument: ${flag}`);
    if (values.has(flag)) throw new Error(`Duplicate ${flag}`);
    if (value === undefined) throw new Error(`${flag} requires a path`);
    values.set(flag, value);
  }
  if (!values.has('--before') || !values.has('--after')) {
    throw new Error('review-packet requires both --before <baseline.json> and --after <baseline.json>');
  }
  if (values.has('--rank-before') && !values.has('--rank-after')) {
    throw new Error('--rank-before requires --rank-after (the moved rank-metrics baseline under review)');
  }
  return values;
}

function main(): void {
  const values = parseArguments(process.argv.slice(2));
  const readJson = <T>(path: string): T => JSON.parse(readFileSync(path, 'utf8')) as T;
  const budgets = readJson<{ noise: ReviewPacketNoiseBudgets }>(
    values.get('--budgets') ?? join(EVAL_ROOT, 'budgets.json'),
  );
  // The battery digests the rank approval binds are byte digests of the
  // committed battery files — the same values the machine report records.
  const rankAfterPath = values.get('--rank-after');
  const repoRoot = join(EVAL_ROOT, '..');
  const batteryDigest = (relativePath: string): string =>
    createHash('sha256').update(readFileSync(join(repoRoot, ...relativePath.split('/')))).digest('hex');
  const rank: ReviewPacketRankInput | undefined = rankAfterPath === undefined
    ? undefined
    : {
      before: values.has('--rank-before')
        ? readJson<RankMetricsBaseline>(values.get('--rank-before')!)
        : null,
      after: readJson<RankMetricsBaseline>(rankAfterPath),
      batteryQueriesSha256: batteryDigest(BATTERY_QUERIES_PATH),
      batteryJudgmentsSha256: batteryDigest(BATTERY_JUDGMENTS_PATH),
    };
  const packet = renderBaselineReviewPacket({
    before: readJson<ProbeBaseline>(values.get('--before')!),
    after: readJson<ProbeBaseline>(values.get('--after')!),
    probeFile: readJson<{ probes: Probe[] }>(values.get('--probes') ?? join(EVAL_ROOT, 'probes', 'probes.json')),
    noise: budgets.noise,
    ...(rank === undefined ? {} : { rank }),
  });
  const out = values.get('--out');
  if (out === undefined) process.stdout.write(`${packet}\n`);
  else writeFileSync(out, `${packet}\n`, 'utf8');
  // On stderr so the stdout packet stays byte-pure. A v2 approval quotes this
  // value; the reviewer can re-derive it with sha256sum on the saved packet.
  process.stderr.write(`reviewPacketSha256 (a v2 approval quotes this): ${reviewPacketSha256(packet)}\n`);
}

const executedDirectly = process.argv[1] !== undefined
  && import.meta.url === pathToFileURL(process.argv[1]).href;
if (executedDirectly) {
  try {
    main();
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}
